<?php
declare(strict_types=1);

// POP3/IMAP default program on Ubuntu: Dovecot (one daemon serves both).
// Hosted-mail configuration is generated by `kloxo-mail apply`; this driver
// only installs the packages and starts/stops the systemd unit.
class Pop3__dovecot extends lxDriverClass
{
	static function installMe()
	{
		lxshell_return('apt-get', 'install', '-y',
			'dovecot-core', 'dovecot-imapd', 'dovecot-pop3d', 'dovecot-lmtpd',
			'dovecot-mysql', 'dovecot-sieve', 'dovecot-managesieved');
		lxshell_return('systemctl', 'enable', 'dovecot');
		lxshell_return('systemctl', 'start', 'dovecot');
	}

	static function unInstallMe()
	{
		lxshell_return('systemctl', 'stop', 'dovecot');
		lxshell_return('systemctl', 'disable', 'dovecot');
	}
}
